const t={ui:{fig:"Fig. 1",title:"Porta cellulare · anatomia",svgLabel:"Un disegno isometrico della pochette porta cellulare foderata con patta e tre scomparti e di come si cuce, passo dopo passo.",prev:"Passo precedente",dot:(a,e)=>a?`Passo ${a}: ${e}`:e,start:"Passo passo →",next:"Avanti →",overview:"Panoramica",stepOf:(a,e)=>`Passo ${a} di ${e}`,machine:a=>`Macchina: ${a.toLowerCase()}`,inThisStep:"In questo passo",takeApart:"Smonta",putTogether:"Rimonta",replay:"↻ Rivedi",parts:"Parti",allSteps:"Istruzioni passo passo",endView:"SEZIONE",cutTitle:"Porta cellulare · misure di taglio",cutAlt:"Schema di taglio di una pochette porta cellulare foderata con patta: esterno, fodera e teletta termoadesiva, ciascuno in un pezzo lungo di 57 × 19 cm e un pezzo per la patta di 31 × 13 cm, più due quadrati di 5 × 5 cm per i passanti.",cutCaption:"I pezzi da tagliare, con le loro misure — come al passo 1."},stitches:{straight:"Punto dritto"},labels:{cm57:"57 cm",cm19:"19 cm",cm31:"31 cm",cm13:"13 cm",cm5:"5 cm",cm11:"11 cm",outerPrint:"esterno · cotone stampato",liningSame:"fodera · stesse misure",ifaceSame:"teletta · stesse misure",flapPieces:"pezzi della patta",ears2:"2 × passanti",wrongSideUp:"esterno, rovescio su",ironOn:"stira",outerOnly:"solo sull'esterno",faceDown:"dritto sotto, al centro",seam05:"cucitura a 0,5 cm",openOut:"apri: una T",liningSameT:"fodera: la stessa T",rightSides:"dritto contro dritto",roundObject:"un coperchio qualsiasi",roundCorners:"angoli tondi",opening6:"apertura di 6 cm",oppositeFlap:"di fronte alla patta",clipCorners:"taglietti agli angoli",turnOut:"rivolta sul dritto",press:"stira",topstitch05:"impuntura a 0,5 cm",closesOpening:"chiude l'apertura",turnOver:"fodera sopra",foldHalf:"piega a metà",fromFold:"dalla piega",throughBoth:"su entrambi gli strati",twoLines:"due cuciture",openFlap:"apri la patta",seamsMiddle:"cuciture al centro",accordion:"a fisarmonica",pockets2:"2 scomparti",pocket3:"il 3° scomparto",edgesIn:"bordi al centro",intoLoop:"piega ad anello",makeTwo:"fanne due",overTop:"ripiega",backAndFlap:"retro + patta",earsIn:"passanti in alto",clipIt:"fissa i lati",edgeStitch:"a filo del bordo",backAndNext:"retro + strato accanto",snapFlap:"bottone: centro patta",whereItLands:"dove arriva",secondHalf:"seconda metà",phone:"cellulare",money:"soldi",cards:"carte",chainOn:"catena con moschettoni"},steps:[{title:"La pochette finita",text:"Una piccola pochette foderata per il cellulare, i soldi e le carte: tre scomparti dentro, una patta con un bottone a pressione di plastica e due piccoli passanti in alto. La catena è solo un'idea — nel video non c'è; ai passanti si aggancia qualsiasi catena o tracolla con moschettoni. Tocca la pochette per smontarla."},{title:"Taglia i pezzi",text:"Esterno in cotone stampato: un pezzo lungo di 57 × 19 cm e un pezzo per la patta di 31 × 13 cm. Fodera e teletta termoadesiva: le stesse due misure. Due quadrati di 5 × 5 cm per i passanti.",details:["Dal cotone stampato taglia il pezzo lungo di 57 × 19 cm e il pezzo per la patta di 31 × 13 cm.","Taglia la fodera allo stesso modo: 57 × 19 cm e 31 × 13 cm.","Taglia la teletta termoadesiva nelle stesse due misure — solo per i pezzi esterni.","Per i passanti taglia due quadrati di 5 × 5 cm dal cotone stampato.","Tutti i margini di cucitura di questa pochette sono di 0,5 cm."]},{title:"Applica la teletta",text:"Stira la teletta sul rovescio dei due pezzi esterni. La fodera non ne ha.",details:["Disponi il pezzo lungo esterno e il pezzo della patta con il rovescio verso l'alto.","Appoggia sopra la teletta, lato colla in basso, bordo contro bordo, e stirala.","I pezzi di fodera non ricevono teletta."]},{title:"Cuci la T",text:"Appoggia il pezzo della patta dritto contro dritto di traverso al centro del pezzo lungo, il suo lato di 13 cm sul lato lungo. Cuci a 0,5 cm dal bordo e apri: una T. Con la fodera fai la stessa T.",details:["Disponi il pezzo lungo con il dritto verso l'alto.","Appoggia sopra il pezzo della patta, dritto verso il basso, di traverso: il suo lato di 13 cm esattamente al centro di un lato lungo, bordo contro bordo.","Cuci lungo quel bordo a 0,5 cm e apri il pezzo della patta: i due pezzi formano una T.","Con i pezzi di fodera cuci allo stesso modo un'altra T."]},{title:"Arrotonda la patta",text:"Appoggia la T di fodera sulla T esterna, dritto contro dritto. Arrotonda i due angoli in fondo alla patta: traccia il contorno di un oggetto rotondo qualsiasi e taglia lungo la linea.",details:["Appoggia la T di fodera con il dritto verso il basso sulla T esterna, bordi pari, e fermale con le clip per cucito.","In fondo al pezzo della patta traccia il contorno di un oggetto rotondo qualsiasi — il coperchio di un barattolo, un rotolo di nastro adesivo — su entrambi gli angoli.","Taglia lungo le linee: la patta ha gli angoli tondi."]},{title:"Cuci tutto intorno",text:"Cuci tutto intorno a 0,5 cm dal bordo, lasciando un'apertura di 6 cm al centro del lato lungo, di fronte alla patta. Fai dei taglietti agli angoli.",details:["Comincia da un'estremità dell'apertura: i 6 cm restano aperti, al centro del lato lungo, di fronte al pezzo della patta.","Cuci tutto il contorno della T a 0,5 cm dal bordo e fermati all'altra estremità dell'apertura.","Fai un taglietto nel margine dei due angoli interni della T — prima della linea di cucitura — e sugli angoli tondi, perché restino piatti."]},{title:"Rivolta",text:"Rivolta la T sul dritto attraverso l'apertura. Fai uscire bene gli angoli e stira.",details:["Tira fuori tutta la T dall'apertura.","Fai uscire gli angoli e la punta arrotondata della patta.","Stira bene in piano, con i bordi dell'apertura ripiegati all'interno."]},{title:"Impuntura tutto intorno",text:"Impuntura tutta la T a 0,5 cm dal bordo. La stessa impuntura chiude anche l'apertura.",details:["Cuci lungo tutto il bordo, a 0,5 cm.","In corrispondenza dell'apertura tieni pari i bordi ripiegati: l'impuntura la chiude."]},{title:"Piega e segna",text:"Gira la T con la fodera in su e piega a metà il pezzo lungo — il pezzo della patta si piega a metà per il lungo. Segna due linee a 11 e 22 cm dalla piega.",details:["Gira la T con la fodera verso l'alto.","Piega a metà il pezzo lungo, fodera all'interno: la piega passa al centro del pezzo della patta, che si piega a metà per il lungo.","Con il metro da sarta misura 11 cm dalla piega e poi altri 11 cm da quel segno: linee a 11 e 22 cm dalla piega. Tracciale con il righello."]},{title:"Cuci le due linee",text:"Cuci entrambe le linee su tutte e due le metà. Le metà ora sono unite: queste cuciture dividono la pochette in scomparti.",details:["Cuci la prima linea su entrambi gli strati.","Cuci la seconda linea allo stesso modo.","Tra la piega e la prima cucitura, e tra le due cuciture, le metà formano due anelli."]},{title:"Piega a fisarmonica",text:"Riapri in piano il pezzo della patta. Gli anelli si aprono, le cuciture vanno al centro e il pezzo lungo si piega a fisarmonica: due scomparti.",details:["Apri in piano il pezzo della patta.","Appiattisci il pezzo lungo in modo che il suo centro — la piega — stia in fondo al pezzo della patta e le due cuciture vadano al centro.","Si piega a fisarmonica: due scomparti, uno dietro l'altro. Il terzo si forma al passo 12."]},{title:"Prepara i passanti",text:"Piega ogni quadrato di 5 × 5 cm in una striscia stretta: a metà, i due bordi verso la piega, di nuovo a metà. Poi piega la striscia a metà ad anello. Fanne due.",details:["Piega il quadrato a metà e riaprilo.","Porta entrambi i bordi fino a quella piega e piega di nuovo a metà: una striscia stretta di quattro strati.","Piega la striscia a metà in un piccolo anello. Fanne due."]},{title:"Ripiega la patta",text:"Ripiega il lungo pezzo della patta sopra gli scomparti: passa sotto il fondo e risale lungo il retro, la sua estremità sporge in alto e diventa la patta. Tra il retro e gli scomparti si forma il terzo scomparto. Infila un passante in ogni lato in alto, tra il retro e gli scomparti.",details:["Ripiega il pezzo della patta sopra gli scomparti. La sua piega è il fondo della pochette e chiude in basso ogni scomparto.","Il resto è il retro; la sua estremità sporge in alto — è la patta. Tra il retro e gli scomparti: il terzo scomparto.","Infila un passante in ogni lato in alto, tra il retro e gli scomparti, con l'anello verso l'esterno.","Fissa i lati con le clip per cucito."]},{title:"Cuci i lati",text:"Cuci entrambi i lati a filo del bordo: sul retro, sullo strato accanto e sui passanti. Le pieghe della fisarmonica restano libere.",details:["Cuci un lato a filo del bordo: sul retro, sullo strato accanto e sul passante. Le pieghe degli scomparti a fisarmonica non vengono cucite — la sezione mostra dove passa la cucitura.","Cuci l'altro lato allo stesso modo."]},{title:"Metti il bottone",text:"Applica una metà del bottone a pressione di plastica al centro della patta, sull'impuntura. Abbassa la patta, segna dove arriva e applica lì l'altra metà.",details:["Applica la prima metà del bottone al centro della punta arrotondata della patta, sulla linea dell'impuntura.","Abbassa la patta sul davanti e segna dove arriva il bottone.","Applica lì la seconda metà."]},{title:"Riempi la pochette",text:"Apri la patta: il cellulare nello scomparto vicino al retro, i soldi in quello centrale, le carte in quello davanti. Chiudi la patta. Per portarla, aggancia ai passanti una catena o una tracolla con moschettoni — nel video non c'è, scegli quella che ti piace.",details:["Il cellulare — nello scomparto vicino al retro.","I soldi — nello scomparto centrale.","Le carte — nello scomparto davanti.","Chiudi la patta con il bottone.","Aggancia ai passanti una catena o una tracolla con moschettoni. Nel video non c'è — va bene quella che preferisci."]}],legend:[{title:"Esterno",text:"cotone stampato · pezzo lungo di 57 × 19 cm e pezzo della patta di 31 × 13 cm"},{title:"Teletta",text:"termoadesiva · le stesse due misure, solo sui pezzi esterni"},{title:"Fodera",text:"cotone rosa · le stesse due misure, senza teletta"},{title:"Patta",text:"il pezzo di 31 × 13 cm: sotto il fondo, su per il retro, angoli tondi in fondo"},{title:"Scomparti ×3",text:"due nella fisarmonica (cuciture a 11 e 22 cm dalla piega su entrambe le metà), il terzo tra questa e il retro: carte, soldi, cellulare"},{title:"Passanti ×2",text:"quadrati di 5 × 5 cm, piegati in una striscia stretta, poi ad anello"},{title:"Bottone",text:"a pressione, di plastica · al centro della patta, sull'impuntura"},{title:"Cuciture",text:"tutte a 0,5 cm · apertura di 6 cm di fronte alla patta, chiusa dall'impuntura a 0,5 cm tutto intorno"}]};export{t as default};
